arguments.command:
curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" -d token=<TOKEN> | python3 -c "
import json,sys
d=json.load(sys.stdin)
print('ok:',d.get('ok'))
for u in d.get('members',[]):
    if not u.get('is_bot') and not u.get('deleted'):
        rn=(u.get('profile') or {}).get('real_name','')
        if 'tara' in rn.lower() or 'reyes' in rn.lower() or 'tara' in (u.get('username') or '').lower():
            print(u['id'],'|',u.get('username'),'|',rn)
"

